mapper.select:
SELECT ,
       DATEDIFF(maturity_date, CURDATE()) AS d_day
FROM user_deposits
WHERE user_deposit_id = #{userDepositId}
  AND user_id = #{userId}
  AND is_deleted = 'N'

mapper.update:
UPDATE user_deposits
SET is_deleted = 'Y',
    updated_by = #{userId}
WHERE user_deposit_id = #{userDepositId}
  AND user_id = #{userId}
  AND is_deleted = 'N'
